  LinkedList<ZKUtilOp> singleDelete=new LinkedList<>();
  singleDelete.add(ZKUtilOp.deleteNodeFailSilent(path));
  ZKUtil.multiOrSequential(zkw,singleDelete,false);
  assertEquals(-1,ZKUtil.checkExists(zkw,path));
}
