/** 
 * Test that we can interrupt a node that is blocked on a wait.
 */
@Test public void testInterruptible() throws IOException, InterruptedException {
  Abortable abortable=new StubAbortable();
  ZKWatcher zk=new ZKWatcher(TEST_UTIL.getConfiguration(),"testInterruptible",abortable);
  final TestTracker tracker=new TestTracker(zk,"/xyz",abortable);
  tracker.start();
  Thread t=new Thread(() -> {
    try {
      tracker.blockUntilAvailable();
    }
 catch (    InterruptedException e) {
      throw new RuntimeException("Interrupted",e);
    }
  }
);
  t.start();
  while (!t.isAlive()) {
    Threads.sleep(1);
  }
  tracker.stop();
  t.join();
}
,flaky

@Test public void multiExecuteValidTest() throws Exception {
  setUp(100,"hello","world");
  ExecutorService pool=Executors.newFixedThreadPool(100);
  List<Future<?>> futures=new ArrayList<Future<?>>(10000);
  for (int i=0; i < 10000; i++) {
    final EchoInfo echoInfo=EchoInfo.newBuilder().setMessage(i + "").build();
    final int order=i;
    Runnable runnable=new Runnable(){
      public void run(){
        try {
          EchoInfo echo=echoService.echo(echoInfo);
          Assert.assertEquals("hello:" + order,echo.getMessage());
        }
 catch (        Exception e) {
          e.printStackTrace();
        }
      }
    }
;
    Future<?> submit=pool.submit(runnable);
    futures.add(submit);
  }
  for (  Future<?> future : futures) {
    future.get();
  }
  pool.shutdown();
}
