"+ "  text: "",
"+ "  flag: false,
"+ "  b: 0,
"+ "  s: 0,
"+ "  ch: "\0",
"+ "  i: 0,
"+ "  f: 0.0,
"+ "  d: 0.0,
"+ "  l: 0
"+ "}
"+ "]
"+ "gmbb.method3[method3]
"+ "gmbz.method3[method3]
",sw.toString().replace("",""));
}
