@Test public void testAllowNullSchema() throws JSONException {
  JSONSchema<Foo> jsonSchema=JSONSchema.of(SchemaDefinition.<Foo>builder().withPojo(Foo.class).build());
  Assert.assertEquals(jsonSchema.getSchemaInfo().getType(),SchemaType.JSON);
  Schema.Parser parser=new Schema.Parser();
  parser.setValidateDefaults(false);
  String schemaJson=new String(jsonSchema.getSchemaInfo().getSchema());
  assertJSONEqual(schemaJson,SCHEMA_JSON_ALLOW_NULL);
  Schema schema=parser.parse(schemaJson);
  for (  String fieldName : FOO_FIELDS) {
    Schema.Field field=schema.getField(fieldName);
    Assert.assertNotNull(field);
    if (field.name().equals("field4")) {
      Assert.assertNotNull(field.schema().getTypes().get(1).getField("field1"));
    }
    if (field.name().equals("fieldUnableNull")) {
      Assert.assertNotNull(field.schema().getType());
    }
  }
}
,not_flaky

@Test void shouldSettersWithUnrelatedArgTypesThrowException() throws Exception {
@SuppressWarnings("unused") class BeanClass {
    public void setProp1(    String arg){
    }
    public void setProp2(    String arg){
    }
    public void setProp2(    Integer arg){
    }
    public void setProp2(    boolean arg){
    }
  }
  ReflectorFactory reflectorFactory=new DefaultReflectorFactory();
  Reflector reflector=reflectorFactory.findForClass(BeanClass.class);
  List<String> setableProps=Arrays.asList(reflector.getSetablePropertyNames());
  assertTrue(setableProps.contains("prop1"));
  assertTrue(setableProps.contains("prop2"));
  assertEquals("prop1",reflector.findPropertyName("PROP1"));
  assertEquals("prop2",reflector.findPropertyName("PROP2"));
  assertEquals(String.class,reflector.getSetterType("prop1"));
  assertNotNull(reflector.getSetInvoker("prop1"));
  Class<?> paramType=reflector.getSetterType("prop2");
  assertTrue(String.class.equals(paramType) || Integer.class.equals(paramType) || boolean.class.equals(paramType));
  Invoker ambiguousInvoker=reflector.getSetInvoker("prop2");
  Object[] param=String.class.equals(paramType) ? new String[]{"x"} : new Integer[]{1};
  when(() -> ambiguousInvoker.invoke(new BeanClass(),param));
  then(caughtException()).isInstanceOf(ReflectionException.class).hasMessageMatching("Ambiguous setters defined for property 'prop2' in class '" + BeanClass.class.getName().replace("$","\\$") + "' with types '(java.lang.String|java.lang.Integer|boolean)' and '(java.lang.String|java.lang.Integer|boolean)'\\.");
}
,not_flaky

